implementation.css_variables:
:root {
  --font-display: 'Tyros Pro', 'Tiempos Headline', Georgia, 'Times New Roman', serif;
  --font-body: 'SubjectivitySerif', 'Source Serif Pro', Georgia, 'Times New Roman', serif;
  --font-mono: 'Fira Code', 'SFMono-Regular', 'JetBrains Mono', Menlo, Consolas, monospace;
  --type-base: 16px;
  --type-ratio: 1.25;
  --leading-tight: 1.08;
  --leading-normal: 1.5;
  --leading-relaxed: 1.625;
  --tracking-display: -0.02em;
  --tracking-label: 0.08em;
}
